'use client';
const require_fieldset = require("./fieldset.cjs");
const require_fieldset_description = require("./fieldset-description.cjs");
const require_fieldset_legend = require("./fieldset-legend.cjs");
//#region src/components/fieldset/index.ts
/**
* Fieldset component, used to wrap a form field.
*
* @example
* <Fieldset>
*   <Fieldset.Legend>Skriv inn dine svar</Fieldset.Legend>
*   <Fieldset.Description>
*     Gi en kort beskrivelse i begge feltene
*   </Fieldset.Description>
*   <Field>
*     <Label>Kort beskrivelse</Label>
*     <Input />
*   </Field>
* </Fieldset>
*/
const FieldsetComponent = Object.assign(require_fieldset.Fieldset, {
	Legend: require_fieldset_legend.FieldsetLegend,
	Description: require_fieldset_description.FieldsetDescription
});
FieldsetComponent.Legend.displayName = "Fieldset.Legend";
FieldsetComponent.Description.displayName = "Fieldset.Description";
//#endregion
exports.Fieldset = FieldsetComponent;
exports.FieldsetDescription = require_fieldset_description.FieldsetDescription;
exports.FieldsetLegend = require_fieldset_legend.FieldsetLegend;
